import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.CyZTVJbV.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.10/x-thread-en.md","filePath":"announcements/v1.10/x-thread-en.md"}'),i={name:"announcements/v1.10/x-thread-en.md"};function n(o,e,p,c,d,l){return t(),s("div",null,[...e[0]||(e[0]=[r('<p>1/ 🌱 kiwa v1.10 shipped — 3-axis parallel expansion: SaaS + self-host + polyglot.</p><p>After v1.9 filled the provider gap for auth / queue / cache, v1.10 opens 3 new dimensions.</p><p>Supabase Auth (core + advanced), RabbitMQ (basic + advanced), Rust contract layer (Foundry-rs + alloy.rs).</p><p>6/6 sub-issues resolved.</p><p>2/ <code>@kiwa-lab/auth</code> v0.3 — Supabase Auth (2 adapters).</p><p>Core: PKCE OAuth, magic link, SMS OTP, JWT HS256 + refresh rotation.</p><p>Advanced: RLS policy sim (SELECT/INSERT/UPDATE/DELETE + service_role bypass), MFA (TOTP RFC 6238 + backup codes + SMS AAL upgrade), SSO SAML 2.0 (SP-initiated + tampering detect), Web3 SIWE (EIP-4361 + replay protection).</p><p>3/ <code>@kiwa-lab/queue</code> v0.3 — RabbitMQ (2 adapters).</p><p>Basic: 4 exchange type (direct / topic / fanout / headers with wildcards + x-match), consumer + ack/nack, prefetch QoS, mandatory return.</p><p>Advanced: DLX + maxDeliveries, delayed message plugin (<code>x-delayed-message</code> + deterministic advanceClock), 3-node cluster + quorum queue + assertQuorumHealthy, federation upstream/link, amqp-connection-manager exponential backoff.</p><p>4/ <code>kiwa-test-rs</code> v0.4.2 — Rust contract layer.</p><p>Foundry adapter: FoundryEnv::detect graceful skip, Anvil::spawn_deterministic + Drop cleanup + wait_ready TCP probe, forge test + coverage (summary + lcov), cast call/send/rpc wrappers.</p><p>alloy adapter: SolAbi JSON parser, built-in keccak-256 selector, Signer enum (LocalWallet / AwsKms / Ledger / Trezor), Provider enum (Http / Ws / Ipc), ContractCall encoding.</p><p>Zero heavy deps — neither module pulls the alloy crate family.</p><p>5/ Layer 1 spec + skill chain extended.</p><p><code>/kiwa-design --layer contract-rust --provider {foundry|alloy}</code> now emits 9-column extended table for Rust contract tests (target contract / method / call direction / signer / provider / assertion type).</p><p>Layer 2 <code>/kiwa-rust --layer contract-rust --provider ...</code> reads the spec and generates the Rust test file.</p><p>6/ Zero-migration for v1.9 users.</p><p>Existing test files keep working. v1.10 additions are all opt-in (feature-gated on Rust, new function calls on TS).</p><p>Rust update:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kiwa-test-rs = { version = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.4.2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, features = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;contract-foundry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;contract-alloy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>7/ v1.10 milestone: <a href="https://github.com/cardene777/kiwa/issues/666" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/issues/666</a></p><p>Next up: v1.11 candidates include Storybook integration, Dragonfly (2025 new cache), Reth (Rust Ethereum execution client), Go Iris + Chi (framework depth).</p><p>Follow @cardene777 for kiwa release cadence.</p>',24)])])}const k=a(i,[["render",n]]);export{h as __pageData,k as default};
